fn take(arr: Vec<f32>, indices: Vec<usize>) -> Vec<f32> {
    // Pre-allocate a result vector with the exact needed capacity
    let mut result = Vec::with_capacity(indices.len());

    // For each index, push the corresponding element from `arr`
    for i in indices {
        // Since f32 implements `Copy`, indexing `arr[i]` yields a copy of the value
        result.push(arr[i]);
    }

    result
}

